typedef struct {
    uint64_t key;
    uint64_t value;
} z_t1260_entry_t;

typedef struct z_t1260_t {
    uint32_t length;
    uint32_t capacity;
    uint32_t* indices;
    z_t1260_entry_t* entries;
} z_t1260_t;

